import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 msgValue, address adr, bytes calldata data) public {
        // Restrict to avoid overflow in balance arithmetic; keep domain wide.
        vm.assume(adr != address(c));
        vm.assume(msgValue > 0);

        // Fund the contract so it has a balance >= msgValue (preconditions)
        vm.deal(address(c), msgValue * 2);
        uint256 preBalance = address(c).balance;

        vm.deal(c.Owner(), msgValue);
        vm.prank(c.Owner());
        c.Command{value: msgValue}(adr, data);

        // General property: post-call contract balance should be exactly preBalance - msgValue.
        // The bug sends the entire balance, breaking this equality when msgValue > 0.
        assertEq(address(c).balance, preBalance - msgValue);
    }
